def load() -> pd.DataFrame:
    import pandas as pd
    import glob

    pattern = 'data/wildfire/input/ZHVI.csv'
    matches = glob.glob(pattern)
    if not matches:
        # Try case-insensitive-ish common variants in case the provided path casing differs on disk
        alt_matches = []
        alt_matches += glob.glob('data/wildfire/input/zhvi*.csv')
        alt_matches += glob.glob('data/wildfire/input/ZHVI*.csv')
        alt_matches += glob.glob('data/wildfire/input/*ZHVI*.csv')
        if alt_matches:
            matches = sorted(set(alt_matches))
        else:
            raise FileNotFoundError(
                f"No files matched '{pattern}'. Also tried: "
                f"data/wildfire/input/zhvi*.csv, data/wildfire/input/ZHVI*.csv, data/wildfire/input/*ZHVI*.csv"
            )

    path = sorted(matches)[0]
    return pd.read_csv(path)

def load() -> pd.DataFrame:
    import json
    import pandas as pd

    path = 'data/wildfire/input/state_abbreviation_to_state.json'
    with open(path, 'r', encoding='utf-8') as f:
        d = json.load(f)

    # Expect mapping like {"CA": "California", ...}
    return pd.DataFrame([{'state_abbr': k, 'state_full': v} for k, v in d.items()])

