def process(zhvi, stateMap) -> pd.DataFrame:
    import pandas as pd
    import numpy as np
    import re

    df = zhvi.copy()

    # --- identify state column ---
    preferred = [
        'state', 'State', 'state_abbr', 'StateName', 'state_name',
        'RegionName', 'regionname', 'Region', 'region'
    ]
    state_col = None
    for c in preferred:
        if c in df.columns:
            state_col = c
            break
    if state_col is None:
        # regex fallback
        for c in df.columns:
            if re.search(r'(?i)\bstate\b', str(c)) or re.search(r'(?i)state', str(c)):
                state_col = c
                break

    if state_col is None:
        # Cannot proceed; return diagnostic
        return pd.DataFrame([{
            'error': 'Could not identify a state column in ZHVI table',
            'columns': ','.join(map(str, df.columns[:50]))
        }])

    # --- detect time series columns ---
    def parse_date_like(col):
        s = str(col)
        # accept YYYY, YYYY-MM, YYYY-MM-DD
        if re.fullmatch(r'\d{4}', s):
            return pd.Timestamp(f'{s}-01-01')
        if re.fullmatch(r'\d{4}-\d{2}', s):
            return pd.Timestamp(f'{s}-01')
        if re.fullmatch(r'\d{4}-\d{2}-\d{2}', s):
            return pd.Timestamp(s)
        return None

    date_cols = []
    for c in df.columns:
        ts = parse_date_like(c)
        if ts is not None:
            date_cols.append((c, ts))

    if not date_cols:
        return pd.DataFrame([{
            'error': 'Could not detect any time-series columns (YYYY / YYYY-MM / YYYY-MM-DD) in ZHVI table',
            'state_col': state_col,
            'n_cols': len(df.columns)
        }])

    date_df = pd.DataFrame(date_cols, columns=['col', 'ts'])

    # endpoints inclusive between 2005 and 2010
    start2005 = pd.Timestamp('2005-01-01')
    end2005 = pd.Timestamp('2005-12-31')
    start2010 = pd.Timestamp('2010-01-01')
    end2010 = pd.Timestamp('2010-12-31')

    cols_2005 = date_df[(date_df['ts'] >= start2005) & (date_df['ts'] <= end2005)].sort_values('ts')
    cols_2010 = date_df[(date_df['ts'] >= start2010) & (date_df['ts'] <= end2010)].sort_values('ts')

    if cols_2005.empty or cols_2010.empty:
        return pd.DataFrame([{
            'error': 'Missing required year columns',
            'state_col': state_col,
            'min_ts': date_df['ts'].min(),
            'max_ts': date_df['ts'].max(),
            'n_2005_cols': int(cols_2005.shape[0]),
            'n_2010_cols': int(cols_2010.shape[0])
        }])

    # Use the earliest available observation in 2005 and the latest in 2010
    col_2005 = cols_2005.iloc[0]['col']
    col_2010 = cols_2010.iloc[-1]['col']

    # --- compute loss without dropping rows unnecessarily ---
    v2005 = pd.to_numeric(df[col_2005], errors='coerce')
    v2010 = pd.to_numeric(df[col_2010], errors='coerce')
    loss = v2005 - v2010

    out = pd.DataFrame({
        'state_raw': df[state_col].astype(str),
        'value_2005_col': col_2005,
        'value_2010_col': col_2010,
        'loss': loss
    })

    # If state column is actually RegionName, it may contain full state names already.
    # We'll try to map abbreviations first when state_raw is 2-letter.
    out['state_abbr'] = out['state_raw'].where(out['state_raw'].str.fullmatch(r'[A-Z]{2}'))

    # Aggregate total loss by state_raw (or abbr when available)
    # Use min_count=1 to avoid turning all-NaN groups into 0.
    grouped = (
        out.assign(state_key=np.where(out['state_abbr'].notna(), out['state_abbr'], out['state_raw']))
           .groupby('state_key', dropna=False)['loss']
           .sum(min_count=1)
           .reset_index(name='total_loss')
    )

    # Keep only positive loss (value decrease)
    grouped = grouped[grouped['total_loss'] > 0].copy()

    # Map abbreviations to full names where possible
    sm = stateMap.copy()
    sm['state_abbr'] = sm['state_abbr'].astype(str)
    grouped = grouped.merge(sm, left_on='state_key', right_on='state_abbr', how='left')
    grouped['state_full_final'] = grouped['state_full'].fillna(grouped['state_key'])

    top3 = grouped.sort_values('total_loss', ascending=False).head(3)

    return top3[['state_full_final', 'total_loss', 'value_2005_col', 'value_2010_col']].rename(
        columns={'state_full_final': 'state_full'}
    )
